function formatPhone(raw: string): string {
    const digits = raw.replace(/\D/g, "")
    if (digits.length !== 12) return "noto'g'ri raqam"
    return `+${digits.slice(0, 3)} (${digits.slice(3, 5)}) ${digits.slice(5, 8)}-${digits.slice(8, 10)}-${digits.slice(10)}`
}

